/* LazDatasnap local Chart-compatible lightweight runtime */
window.Chart=window.Chart||function(ctx,cfg){this.ctx=ctx;this.config=cfg||{};var c=ctx&&ctx.canvas?ctx.canvas:ctx;if(c&&c.getContext){var g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);g.font='16px sans-serif';g.fillText((cfg&&cfg.type?cfg.type:'chart')+' preview',20,30);}return this;};